import OrbitingCircles from "@/components/OrbitingCircles";

export function DemoOrbitingCircles() {
  return (
    <div className="relative flex h-[500px] w-full flex-col items-center justify-center overflow-hidden rounded-lg md:h-[700px]">
      <span className="pointer-events-none whitespace-pre-wrap bg-gradient-to-b from-black to-gray-300 bg-clip-text text-center text-2xl font-semibold leading-none text-transparent md:text-4xl">
        Tech Stack
      </span>

      {/* Inner Circles */}
      <OrbitingCircles
        className="size-[20px] md:size-[30px] bg-white"
        duration={20}
        delay={20}
        radius={60}
      >
        <Icons.javascript />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[20px] md:size-[30px] border-none bg-transparent"
        duration={20}
        delay={10}
        radius={60}
      >
        <Icons.notion />
      </OrbitingCircles>

      {/* Outer Circles (reverse) */}
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-none bg-transparent"
        radius={140}
        duration={20}
        delay={12}
        reverse
      >
        <Icons.react />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-none bg-white"
        radius={140}
        duration={20}
        delay={10}
        reverse
      >
        <Icons.tailwind />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-white bg-white"
        radius={140}
        duration={20}
        delay={20}
        reverse
      >
        <Icons.nodeJs />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-white bg-white"
        radius={140}
        duration={20}
        delay={27}
        reverse
      >
        <Icons.nextJs />
      </OrbitingCircles>

      {/* outer most circle */}
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-white bg-white"
        radius={200}
        duration={30}
        delay={25}
        reverse
      >
        <Icons.vercel />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-white bg-white"
        radius={200}
        duration={35}
        delay={20}
        reverse
      >
        <Icons.digitalOcean />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[30px] md:size-[45px] border-white bg-white"
        radius={200}
        duration={40}
        delay={15}
        reverse
      >
        <Icons.mongoDb />
      </OrbitingCircles>
    </div>
  );
}


